#include <stdio.h>

int main() {
    int data[] = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3};
    int counts[10] = {0};
    for (int i = 0; i < 10; i++) {
        counts[data[i]]++;
    }
    for (int d = 0; d < 10; d++) {
        if (counts[d] > 0) {
            printf("%d: %d\n", d, counts[d]);
        }
    }
    return 0;
}
